    fn tick12_seed(name: &str, port: &str) -> NewConfig {
        NewConfig {
            name: name.to_string(),
            protocol: "vless".to_string(),
            params: "{\"type\":\"vless\",\"server\":\"198.51.100.9\",\"server_port\":443,\
                \"uuid\":\"11111111-2222-4333-8444-555555555555\",\"encryption\":\"none\",\
                \"security\":\"tls\",\"sni\":\"198.51.100.9\",\"network\":\"tcp\"}"
                .to_string(),
            group: String::new(),
            bind_ip: String::new(),
            port: port.to_string(),
        }
    }

    /// Ticks idle with nothing running: no network traffic, no errors, no
    /// crash reports.
    #[gpui_kit::test]
    fn ticks_idle_with_nothing_running_touch_no_network(cx: &mut TestAppContext) {
        use crate::engine::EngineController;
        use crate::health::FakeHealthProber;

        cx.update(gpui_kit::init);

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let store = Store::open_in_memory().expect("in-memory store opens");
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let view = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(view.clone());
            Root::new(view, window, cx)
        });
        let view = stash.borrow().clone().expect("AppView stashed");

        let (prober, handle) = FakeHealthProber::shared();
        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (engine, _) = EngineController::fake();
                view.engine = engine;
                view.prober = Box::new(prober);
            });
        });

        let poll = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_engine_poll(cx)));
        assert_eq!(poll, None, "no crash without a sidecar");
        let subs = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_due_subscriptions(cx)));
        assert_eq!(subs, 0, "no subs, no fetches");
        let reprobed = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_reprobe_running(cx)));
        assert_eq!(reprobed, 0, "nothing running, nothing probed");
        assert!(
            handle.calls_for("1").is_empty() && handle.calls_for("2").is_empty(),
            "idle ticks never touch the network"
        );
        assert!(
            view.read_with(cx, |view, _| view.engine.last_error().is_none()),
            "no errors recorded"
        );
    }

    /// The re-probe tick covers running rows only: records + persists, and
    /// never probes stopped rows.
    #[gpui_kit::test]
    fn tick_reprobe_running_records_and_persists(cx: &mut TestAppContext) {
        use crate::engine::EngineController;
        use crate::health::FakeHealthProber;

        cx.update(gpui_kit::init);

        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store
            .add(tick12_seed("Alpha", "10851"))
            .expect("seed works");
        let beta = store.add(tick12_seed("Beta", "10852")).expect("seed works");

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let view = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(view.clone());
            Root::new(view, window, cx)
        });
        let view = stash.borrow().clone().expect("AppView stashed");

        let (prober, handle) = FakeHealthProber::shared();
        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (engine, _) = EngineController::fake();
                view.engine = engine;
                view.prober = Box::new(prober);
            });
        });
        handle.script_latency(&alpha.id, 21);
        handle.script_failure(&beta.id, "upstream refused");
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.start_all_engines(window, cx));
        });

        let reprobed = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_reprobe_running(cx)));
        assert_eq!(reprobed, 2, "both running rows re-probed");
        // Ticket 26: probes complete off-thread — pump the completion.
        cx.run_until_parked();
        assert_eq!(handle.calls_for(&alpha.id).len(), 1);
        assert_eq!(handle.calls_for(&beta.id).len(), 1);

        let (alpha_live, beta_dead) = view.read_with(cx, |view, _| {
            (
                view.health_store.status(&alpha.id),
                view.health_store.status(&beta.id),
            )
        });
        assert_eq!(alpha_live.latency_ms, Some(21));
        assert!(beta_dead
            .cause
            .as_deref()
            .unwrap_or("")
            .contains("upstream refused"));
        let snaps = view.read_with(cx, |view, _| {
            view.store.load_health_snapshots().expect("snapshots load")
        });
        assert_eq!(snaps.len(), 2, "latest samples persisted");
    }

    /// W2: the re-probe tick never dials rows on crashed shards. After a
    /// crash is observed by the engine poll, the reprobe pass starts nothing
    /// for the crashed rows (no manufactured errors, no health writes), while
    /// surviving siblings keep probing.
    #[gpui_kit::test]
    fn tick_reprobe_skips_rows_on_crashed_shards(cx: &mut TestAppContext) {
        use crate::engine::EngineController;
        use crate::health::FakeHealthProber;

        cx.update(gpui_kit::init);

        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store
            .add(tick12_seed("Alpha", "10861"))
            .expect("seed works");
        let beta = store.add(tick12_seed("Beta", "10862")).expect("seed works");

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let view = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(view.clone());
            Root::new(view, window, cx)
        });
        let view = stash.borrow().clone().expect("AppView stashed");

        let (prober, handle) = FakeHealthProber::shared();
        let stock = cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (engine, stock, _fork) = EngineController::fake_pair();
                view.engine = engine;
                view.prober = Box::new(prober);
                stock
            })
        });
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.start_all_engines(window, cx));
        });
        assert!(
            view.read_with(cx, |view, _| view.engine.is_running(&alpha.id)),
            "rows run before the crash"
        );

        // One crash on the shared stock sidecar; the engine poll observes it
        // (marking the shard crashed) before the next reprobe runs.
        stock.inject_crash("signal: segmentation fault");
        let poll = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_engine_poll(cx)));
        assert!(poll.is_some(), "the crash is reported once");
        assert_eq!(
            view.read_with(cx, |view, _| view.engine.ids_on_crashed_shards().len()),
            2,
            "both stock rows sit on the crashed shard"
        );

        let reprobed = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_reprobe_running(cx)));
        assert_eq!(reprobed, 0, "crashed rows are never re-probed");
        cx.run_until_parked();
        assert!(
            handle.calls_for(&alpha.id).is_empty() && handle.calls_for(&beta.id).is_empty(),
            "no probe ever dials a dead socket"
        );
        let untouched = view.read_with(cx, |view, _| {
            (
                view.health_store.status(&alpha.id),
                view.health_store.status(&beta.id),
            )
        });
        assert!(
            matches!(
                untouched,
                (
                    crate::health::RowHealth {
                        state: crate::health::RowState::Unknown,
                        ..
                    },
                    crate::health::RowHealth {
                        state: crate::health::RowState::Unknown,
                        ..
                    },
                )
            ),
            "no manufactured samples for crashed rows: {untouched:?}"
        );
    }

    /// Restart restores last latencies + dead flags (file-backed store,
    /// second view hydrates with no new probing).
    #[gpui_kit::test]
    fn restart_restores_last_latency_and_dead_flags(cx: &mut TestAppContext) {
        use crate::engine::EngineController;
        use crate::health::FakeHealthProber;

        cx.update(gpui_kit::init);

        let path = std::env::temp_dir().join(format!(
            "manyproxy-tick12-restart-{}.db",
            std::process::id()
        ));
        let _ = std::fs::remove_file(&path);
        let (alpha_id, beta_id) = {
            let mut store = Store::open_file(&path).expect("file store opens");
            let alpha = store
                .add(tick12_seed("Alpha", "10853"))
                .expect("seed works");
            let beta = store.add(tick12_seed("Beta", "10854")).expect("seed works");
            (alpha.id.clone(), beta.id.clone())
        };
        let store = Store::open_file(&path).expect("reopen works");

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let view = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(view.clone());
            Root::new(view, window, cx)
        });
        let view = stash.borrow().clone().expect("AppView stashed");

        let (prober, handle) = FakeHealthProber::shared();
        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (engine, _) = EngineController::fake();
                view.engine = engine;
                view.prober = Box::new(prober);
            });
        });
        handle.script_latency(&alpha_id, 33);
        handle.script_failure(&beta_id, "upstream refused");
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.start_all_engines(window, cx));
        });
        let tested =
            cx.update(|window, cx| view.update(cx, |view, cx| view.test_all_health(window, cx)));
        assert_eq!(tested, 2);
        // Ticket 26: probes complete off-thread — pump the completion.
        cx.run_until_parked();
        drop(view);

        // "Restart": a fresh view over the same file, no probing at all.
        let store = Store::open_file(&path).expect("restart reopen works");
        let stash2: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash2_for_window = stash2.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let restarted = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash2_for_window.borrow_mut() = Some(restarted.clone());
            Root::new(restarted, window, cx)
        });
        let restarted = stash2.borrow().clone().expect("AppView stashed");

        let (live, dead) = restarted.read_with(cx, |view, _| {
            (
                view.health_store.status(&alpha_id),
                view.health_store.status(&beta_id),
            )
        });
        assert_eq!(live.latency_ms, Some(33), "latency survives restart");
        assert!(
            dead.cause
                .as_deref()
                .unwrap_or("")
                .contains("upstream refused"),
            "dead flag + cause survive restart: {:?}",
            dead.cause
        );
        let _ = std::fs::remove_file(&path);
    }

    /// Stopped ticks start nothing even with due subs and running rows (no
    /// telemetry, no auto-start, no fetch beyond due subs — here, no fetch
    /// at all).
    #[gpui_kit::test]
    fn stopped_ticks_start_nothing(cx: &mut TestAppContext) {
        use crate::engine::EngineController;
        use crate::health::FakeHealthProber;

        cx.update(gpui_kit::init);

        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store
            .add(tick12_seed("Alpha", "10855"))
            .expect("seed works");
        store
            .add_subscription("Nightly", "https://example.com/sub.txt", "travel", true)
            .expect("due sub (never refreshed)");

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let view = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(view.clone());
            Root::new(view, window, cx)
        });
        let view = stash.borrow().clone().expect("AppView stashed");

        let (prober, handle) = FakeHealthProber::shared();
        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (engine, _) = EngineController::fake();
                view.engine = engine;
                view.prober = Box::new(prober);
            });
        });
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.start_all_engines(window, cx));
        });
        // The due-sub selection itself is pure (one due sub found).
        assert_eq!(
            view.read_with(cx, |view, _| view.due_subscriptions().len()),
            1
        );

        cx.update(|_, cx| {
            view.update(cx, |view, _| view.stop_background_ticks());
        });
        let poll = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_engine_poll(cx)));
        assert_eq!(poll, None);
        let subs = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_due_subscriptions(cx)));
        assert_eq!(subs, 0, "stopped pass starts no fetch");
        let reprobed = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_reprobe_running(cx)));
        assert_eq!(reprobed, 0, "stopped pass probes nothing");
        assert!(
            handle.calls_for(&alpha.id).is_empty(),
            "stopped ticks never touch the network"
        );
    }

    // -- Ticket 36: data-plane traffic tick ---------------------------------

    /// Stub clash controller: serves one `/connections` body per accepted
    /// connection (Bearer-checked like the real sidecar), then exits.
    fn stub_clash_server(bodies: Vec<String>, secret: &str) -> (u16, std::thread::JoinHandle<()>) {
        use std::io::{Read as _, Write as _};
        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("stub binds");
        let port = listener.local_addr().expect("addr works").port();
        let secret = secret.to_string();
        let server = std::thread::spawn(move || {
            for body in bodies {
                let (mut stream, _) = listener.accept().expect("accept works");
                let mut head = [0u8; 2048];
                let n = stream.read(&mut head).unwrap_or(0);
                let authed = String::from_utf8_lossy(&head[..n])
                    .contains(&format!("Authorization: Bearer {secret}"));
                let (status, payload) = if authed {
                    ("200 OK", body)
                } else {
                    (
                        "401 Unauthorized",
                        r#"{"error":"unauthorized"}"#.to_string(),
                    )
                };
                stream
                    .write_all(
                        format!(
                            "HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{payload}",
                            payload.len()
                        )
                        .as_bytes(),
                    )
                    .expect("reply works");
            }
        });
        (port, server)
    }

    /// One data flow plus one health-probe flow for `row` (synthetic bytes
    /// only — never the live DB, never real credentials).
    fn traffic_body(row: &str, rx: u64, tx: u64) -> String {
        serde_json::json!({
            "connections": [
                {"download": rx, "id": "conn-1",
                 "metadata": {"destinationIP": "93.184.216.34", "destinationPort": "80",
                              "host": "example.com", "network": "tcp",
                              "sourceIP": "127.0.0.1", "sourcePort": "51241",
                              "type": format!("mixed/in-{row}")},
                 "upload": tx},
                {"download": 500, "id": "probe-1",
                 "metadata": {"destinationIP": "93.184.216.34", "destinationPort": "80",
                              "host": "www.gstatic.com", "network": "tcp",
                              "sourceIP": "127.0.0.1", "sourcePort": "51242",
                              "type": format!("mixed/in-{row}")},
                 "upload": 60},
            ],
            "downloadTotal": 1500, "uploadTotal": 110,
        })
        .to_string()
    }

    /// Ticket 36: the traffic tick persists per-row data-plane deltas
    /// (probe flows excluded), mirrors absolutes for display, and never
    /// double-counts a repeated poll.
    #[gpui_kit::test]
    fn tick_traffic_poll_persists_deltas_and_mirrors(cx: &mut TestAppContext) {
        use crate::engine::{ClashTarget, EngineController};

        cx.update(gpui_kit::init);

        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store
            .add(tick12_seed("Alpha", "10856"))
            .expect("seed works");

        let (port, server) = stub_clash_server(
            vec![
                traffic_body(&alpha.id, 1000, 50),
                traffic_body(&alpha.id, 1500, 70),
                traffic_body(&alpha.id, 1500, 70),
            ],
            "s3cret",
        );

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let view = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(view.clone());
            Root::new(view, window, cx)
        });
        let view = stash.borrow().clone().expect("AppView stashed");

        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (mut engine, _) = EngineController::fake();
                engine.set_clash_targets(vec![ClashTarget {
                    core: "stock".to_string(),
                    port,
                    secret: "s3cret".to_string(),
                }]);
                view.engine = engine;
            });
        });

        let updated = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_traffic_poll(cx)));
        assert_eq!(updated, 1, "one row gains data-plane bytes");
        let totals = view.read_with(cx, |view, _| {
            view.store.traffic_totals().expect("totals read")
        });
        assert_eq!(
            totals.get(&alpha.id),
            Some(&(1000, 50)),
            "probe bytes never reach the traffic columns"
        );
        assert_eq!(
            view.read_with(cx, |view, _| view.health_store.data_traffic(&alpha.id)),
            Some((1000, 50)),
            "mirror tracks persisted absolutes"
        );

        let updated = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_traffic_poll(cx)));
        assert_eq!(updated, 1, "grown connections persist the delta");
        let totals = view.read_with(cx, |view, _| {
            view.store.traffic_totals().expect("totals read")
        });
        assert_eq!(totals.get(&alpha.id), Some(&(1500, 70)));

        let updated = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_traffic_poll(cx)));
        assert_eq!(
            updated, 0,
            "identical poll persists nothing (no double count)"
        );
        let totals = view.read_with(cx, |view, _| {
            view.store.traffic_totals().expect("totals read")
        });
        assert_eq!(totals.get(&alpha.id), Some(&(1500, 70)));
        server.join().expect("stub drains");
    }

    /// Ticket 47: the off-UI traffic tick polls concurrently off-thread and
    /// commits on the main thread — deltas persist, the mirror tracks, and
    /// a second tick while one is in flight is skipped, never queued.
    #[gpui_kit::test]
    fn t47_spawn_traffic_poll_off_ui_and_skips_in_flight(cx: &mut TestAppContext) {
        use crate::engine::{ClashTarget, EngineController};

        cx.update(gpui_kit::init);

        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store
            .add(tick12_seed("Alpha", "10858"))
            .expect("seed works");

        let (port, server) = stub_clash_server(vec![traffic_body(&alpha.id, 1000, 50)], "s3cret");

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let view = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(view.clone());
            Root::new(view, window, cx)
        });
        let view = stash.borrow().clone().expect("AppView stashed");

        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (mut engine, _) = EngineController::fake();
                engine.set_clash_targets(vec![ClashTarget {
                    core: "stock".to_string(),
                    port,
                    secret: "s3cret".to_string(),
                }]);
                view.engine = engine;
            });
        });

        // Guard first: a tick already in flight is skipped, never queued.
        cx.update(|_, cx| {
            view.update(cx, |view, _| view.traffic_tick_in_flight = true);
        });
        let skipped = cx.update(|_, cx| view.update(cx, |view, cx| view.spawn_traffic_poll(cx)));
        assert_eq!(skipped, 0, "in-flight tick skipped");
        cx.update(|_, cx| {
            view.update(cx, |view, _| view.traffic_tick_in_flight = false);
        });

        let started = cx.update(|_, cx| view.update(cx, |view, cx| view.spawn_traffic_poll(cx)));
        assert_eq!(started, 1, "poll started off-thread");
        let dup = cx.update(|_, cx| view.update(cx, |view, cx| view.spawn_traffic_poll(cx)));
        assert_eq!(dup, 0, "second tick skipped while one runs");
        // Off-thread completion lands on the main thread.
        cx.run_until_parked();
        let totals = view.read_with(cx, |view, _| {
            view.store.traffic_totals().expect("totals read")
        });
        assert_eq!(
            totals.get(&alpha.id),
            Some(&(1000, 50)),
            "probe bytes never reach the traffic columns"
        );
        assert_eq!(
            view.read_with(cx, |view, _| view.health_store.data_traffic(&alpha.id)),
            Some((1000, 50)),
            "mirror tracks persisted absolutes"
        );
        assert!(
            !view.read_with(cx, |view, _| view.traffic_tick_in_flight),
            "flag clears on completion"
        );
        server.join().expect("stub drains");
    }

    /// Ticket 05 (throne-adoption): multi-flow clash body — one data flow
    /// per `(row, rx, tx)` with a distinct destination, plus the
    /// health-probe flow the Connections pane must exclude. Synthetic bytes
    /// only — never the live DB, never real credentials.
    fn traffic_body_multi(flows: &[(&str, u64, u64)]) -> String {
        let mut connections: Vec<serde_json::Value> = flows
            .iter()
            .enumerate()
            .map(|(ix, (row, rx, tx))| {
                serde_json::json!({
                    "download": rx, "id": format!("conn-{ix}"),
                    "metadata": {"destinationIP": "93.184.216.34", "destinationPort": "80",
                                 "host": format!("flow-{ix}.example.com"), "network": "tcp",
                                 "sourceIP": "127.0.0.1", "sourcePort": "51241",
                                 "type": format!("mixed/in-{row}")},
                    "upload": tx
                })
            })
            .collect();
        connections.push(serde_json::json!({
            "download": 500, "id": "probe-9",
            "metadata": {"destinationIP": "93.184.216.34", "destinationPort": "80",
                         "host": "www.gstatic.com", "network": "tcp",
                         "sourceIP": "127.0.0.1", "sourcePort": "51242",
                         "type": format!("mixed/in-{}", flows[0].0)},
            "upload": 60
        }));
        serde_json::json!({
            "connections": connections,
            "downloadTotal": 1500, "uploadTotal": 110,
        })
        .to_string()
    }

    /// Ticket 05, scenarios 1+2: two exits passing traffic → the Connections
    /// pane shows one row per live connection (exit name + bind:port join,
    /// traffic deltas move on poll) with probe destinations excluded;
    /// click-copies the dest and nothing else.
    #[gpui_kit::test]
    fn t05_connections_snapshot_excludes_probes_and_tracks_deltas(cx: &mut TestAppContext) {
        use crate::engine::{ClashTarget, EngineController};
        use gpui_kit::component::IndexPath;

        cx.update(gpui_kit::init);

        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store
            .add(tick12_seed("Alpha", "10856"))
            .expect("seed works");
        let beta = store.add(tick12_seed("Beta", "10857")).expect("seed works");

        let (port, server) = stub_clash_server(
            vec![
                traffic_body_multi(&[(&alpha.id, 1000, 50), (&beta.id, 3000, 90)]),
                traffic_body_multi(&[(&alpha.id, 1500, 70), (&beta.id, 3600, 120)]),
            ],
            "s3cret",
        );
        let (view, cx) = mount_view(store, cx);
        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (mut engine, _) = EngineController::fake();
                engine.set_clash_targets(vec![ClashTarget {
                    core: "stock".to_string(),
                    port,
                    secret: "s3cret".to_string(),
                }]);
                view.engine = engine;
            });
        });

        let updated = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_traffic_poll(cx)));
        assert_eq!(updated, 2, "both exits gain data-plane bytes");
        // Snapshot: one row per live connection, the probe flow excluded.
        let snapshot = view.read_with(cx, |view, _| view.conn_snapshot.clone());
        assert_eq!(snapshot.len(), 2, "probe flow never reaches the snapshot");
        for (_, entry) in &snapshot {
            assert!(
                !entry.dest.contains("gstatic"),
                "no probe dest in the snapshot: {}",
                entry.dest
            );
        }
        // Display rows sort by traffic, descending by default (Beta first).
        let (first, second) = view.read_with(cx, |view, _| {
            let rows =
                crate::build_conn_rows(&view.conn_snapshot, &view.conn_delta, None, false, true);
            (rows[0].row_id.clone(), rows[1].row_id.clone())
        });
        assert_eq!(first.as_deref(), Some(beta.id.as_str()), "heaviest first");
        assert_eq!(second.as_deref(), Some(alpha.id.as_str()));
        // The exit join names the row honestly (name + bind:port + protocol);
        // unclaimed entries are never guessed.
        let (join, unclaimed) = view.read_with(cx, |view, cx| {
            let rows = view.libraries.read(cx).delegate().rows.clone();
            (
                crate::conn_exit_of(&rows, Some(&alpha.id)),
                crate::conn_exit_of(&rows, Some("no-such-row")),
            )
        });
        assert_eq!(join.0, "Alpha", "exit name joins");
        assert!(
            join.1.ends_with(":10856"),
            "exit bind:port joins: {}",
            join.1
        );
        assert_eq!(
            join.2, "vless",
            "row protocol joins (stored, never sniffed)"
        );
        assert_eq!(
            unclaimed,
            ("unclaimed".to_string(), "—".to_string(), "—".to_string()),
            "unclaimed rows read unclaimed"
        );

        // Second poll: session deltas move, and the hidden-pane throttle
        // holds (the spawn path skips while the 5s base cadence elapses).
        let updated = cx.update(|_, cx| view.update(cx, |view, cx| view.tick_traffic_poll(cx)));
        assert_eq!(updated, 2, "grown connections persist the delta");
        let deltas = view.read_with(cx, |view, _| view.conn_delta.clone());
        assert_eq!(deltas.get("stock/conn-0"), Some(&(500, 20)));
        assert_eq!(deltas.get("stock/conn-1"), Some(&(600, 30)));
        let throttled = cx.update(|_, cx| view.update(cx, |view, cx| view.spawn_traffic_poll(cx)));
        assert_eq!(
            throttled, 0,
            "hidden Connections pane throttles the 1Hz loop to the base cadence"
        );

        // The pane paints one copyable row per live connection; selecting
        // Beta filters to its flow; clicking copies the dest alone.
        cx.update(|_, cx| {
            view.update(cx, |view, cx| {
                view.inspector_tab = crate::InspectorTab::Connections;
                view.conn_selected_only = false;
                view.libraries.update(cx, |state, list_cx| {
                    state.delegate_mut().selected = Some(IndexPath::new(0));
                    list_cx.notify();
                });
                cx.notify();
            });
        });
        cx.run_until_parked();
        paint_frame(cx);
        cx.run_until_parked();
        paint_frame(cx);
        assert_painted(cx, "config-connections");
        assert!(
            cx.update(|window, _| window.try_find("conn-copy-0".to_string()).is_some()),
            "first flow copies"
        );
        assert!(
            cx.update(|window, _| window.try_find("conn-copy-1".to_string()).is_some()),
            "second flow copies"
        );
        cx.update(|_, cx| {
            view.update(cx, |view, cx| {
                view.conn_selected_only = true;
                view.libraries.update(cx, |state, list_cx| {
                    state.delegate_mut().selected = Some(IndexPath::new(1));
                    list_cx.notify();
                });
            });
        });
        cx.run_until_parked();
        paint_frame(cx);
        cx.run_until_parked();
        paint_frame(cx);
        assert!(
            cx.update(|window, _| window.try_find("conn-copy-0".to_string()).is_some()),
            "selected row keeps its flow"
        );
        assert_absent(cx, "conn-copy-1".to_string());
        // Click-copies the dest: the handler path is exercised directly
        // (the inspector has no scroll seam for below-fold clicks — the t06
        // rationale); presence above proves the copy affordance renders.
        cx.update(|window, cx| {
            view.update(cx, |view, cx| {
                view.copy_connection_dest("flow-1.example.com", window, cx)
            });
        });
        let clip = cx.update(|_, cx| {
            cx.read_from_clipboard()
                .and_then(|item| item.text())
                .unwrap_or_default()
                .to_string()
        });
        assert_eq!(clip, "flow-1.example.com", "click copies the dest: {clip}");
        for canary in ["11111111", "198.51.100.9", "uuid", "password"] {
            assert!(
                !clip.contains(canary),
                "connection copy carries the dest only, found {canary}: {clip}"
            );
        }
        server.join().expect("stub drains");
    }

    /// Ticket 05, traffic watcher: per-exit aggregates read heaviest-first
    /// with no fabricated Direct line; idle rows stay quiet.
    #[gpui_kit::test]
    fn t05_traffic_aggregates_per_exit_without_direct(cx: &mut TestAppContext) {
        cx.update(gpui_kit::init);
        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store
            .add(tick12_seed("Alpha", "10856"))
            .expect("seed works");
        let beta = store.add(tick12_seed("Beta", "10857")).expect("seed works");
        store
            .add_traffic_batch(&[(alpha.id.clone(), 1000, 50), (beta.id.clone(), 3000, 90)])
            .expect("traffic persists");
        let rows = store.list().expect("rows list");
        let totals = store.traffic_totals().expect("totals read");
        let exits = crate::aggregate_exit_traffic(&rows, &totals);
        assert_eq!(
            exits.len(),
            2,
            "one aggregate per exit with traffic — never a Direct line"
        );
        assert_eq!(exits[0].row_id, beta.id, "heaviest exit first");
        assert_eq!(exits[1].row_id, alpha.id);
        for exit in &exits {
            assert_ne!(
                exit.name.to_ascii_lowercase(),
                "direct",
                "no fabricated Direct aggregate"
            );
        }
        // An idle row adds no quiet zero bar.
        store
            .add(tick12_seed("Gamma", "10858"))
            .expect("seed works");
        let rows = store.list().expect("rows list");
        let totals = store.traffic_totals().expect("totals read");
        assert_eq!(
            crate::aggregate_exit_traffic(&rows, &totals).len(),
            2,
            "idle rows stay quiet"
        );
    }

    /// Ticket 05, log reader: include narrows, exclude drops the noisy leg,
    /// and regex replaces the keywords — redaction holding on every leg,
    /// invalid patterns failing open, the level row still composing.
    #[gpui_kit::test]
    fn t05_log_include_exclude_regex_keep_redaction(cx: &mut TestAppContext) {
        cx.update(gpui_kit::init);
        let store = Store::open_in_memory().expect("in-memory store opens");
        let (view, cx) = mount_view(store, cx);
        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let tags = crate::health::LogTagIndex::default();
                view.logs
                    .push_raw("info alpha connection established", &tags);
                view.logs.push_raw("info alpha probe finished", &tags);
                view.logs
                    .push_raw("error beta failed password=hunter2-secret", &tags);
                view.log_tail = true;
            });
        });
        cx.update(|_, cx| {
            view.update(cx, |view, cx| {
                view.log_filter = "alpha".to_string();
                view.log_exclude.clear();
                view.log_regex.clear();
                view.log_level = None;
                assert_eq!(view.visible_log_lines(cx).len(), 2, "include narrows");
                view.log_exclude = "probe".to_string();
                assert_eq!(
                    view.visible_log_lines(cx),
                    vec!["[info] info alpha connection established".to_string()],
                    "exclude drops the noisy leg"
                );
                view.log_filter.clear();
                view.log_exclude.clear();
                view.log_regex = "established|failed".to_string();
                let visible = view.visible_log_lines(cx);
                assert_eq!(visible.len(), 2, "regex replaces the keywords");
                for line in &visible {
                    assert!(
                        !line.contains("hunter2-secret"),
                        "redacted on the regex leg: {line}"
                    );
                }
                view.log_regex = "((".to_string();
                assert_eq!(
                    view.visible_log_lines(cx).len(),
                    3,
                    "invalid regex fails open, never a silent empty"
                );
                view.log_regex.clear();
                view.log_level = Some(crate::health::LogLevel::Error);
                let visible = view.visible_log_lines(cx);
                assert_eq!(visible.len(), 1, "level still composes");
                assert!(visible[0].starts_with("[error]"));
                assert!(
                    !visible[0].contains("hunter2-secret"),
                    "redacted on the level leg"
                );
            });
        });
    }

    /// Ticket 05, poll tuning: 1Hz while the Connections/Traffic pane is
    /// visible, else the 5s base cadence. Pure seam over the throttle stamp.
    #[gpui_kit::test]
    fn t05_traffic_poll_cadence_visible_fast_hidden_slow(cx: &mut TestAppContext) {
        cx.update(gpui_kit::init);
        use crate::InspectorTab;
        let now = 1_000_000i64;
        assert!(
            crate::traffic_poll_due(InspectorTab::Connections, now, now),
            "visible Connections polls immediately"
        );
        assert!(
            crate::traffic_poll_due(InspectorTab::Traffic, now, now),
            "visible Traffic polls immediately"
        );
        assert!(
            !crate::traffic_poll_due(InspectorTab::Details, now, now),
            "hidden pane skips a just-ran poll"
        );
        assert!(
            !crate::traffic_poll_due(InspectorTab::Logs, now, now - 4),
            "hidden pane waits the base cadence"
        );
        assert!(
            crate::traffic_poll_due(InspectorTab::Details, now, now - 5),
            "hidden pane fires once the base cadence elapses"
        );
    }

    /// Ticket 36: restart resumes data-plane counters from persisted
    /// totals (never zeroed) with no new polling.
    /// Ticket 47: totals hydrate LAZILY — the fresh view shows no mirror
    /// until the first traffic tick (startup never scans); the first tick
    /// (even with zero targets) restores the counters.
    #[gpui_kit::test]
    fn restart_restores_traffic_mirror(cx: &mut TestAppContext) {
        cx.update(gpui_kit::init);

        let path = std::env::temp_dir().join(format!(
            "manyproxy-tick36-restart-{}.db",
            std::process::id()
        ));
        let _ = std::fs::remove_file(&path);
        let alpha_id = {
            let mut store = Store::open_file(&path).expect("file store opens");
            let alpha = store
                .add(tick12_seed("Alpha", "10857"))
                .expect("seed works");
            store
                .add_traffic(&alpha.id, 1_048_782, 88)
                .expect("traffic persists");
            alpha.id.clone()
        };
        let store = Store::open_file(&path).expect("reopen works");

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let restarted = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(restarted.clone());
            Root::new(restarted, window, cx)
        });
        let restarted = stash.borrow().clone().expect("AppView stashed");

        assert_eq!(
            restarted.read_with(cx, |view, _| view.health_store.data_traffic(&alpha_id)),
            None,
            "lazy totals: no mirror before the first tick"
        );
        let ticked = cx.update(|_, cx| restarted.update(cx, |view, cx| view.tick_traffic_poll(cx)));
        assert_eq!(ticked, 0, "no targets, no rows updated");
        assert_eq!(
            restarted.read_with(cx, |view, _| view.health_store.data_traffic(&alpha_id)),
            Some((1_048_782, 88)),
            "counters resume from persisted totals on first tick"
        );
        // TEMP files auto-removed: swap the view's store for an empty
        // in-memory one (direct field assignment, the fake-engine
        // precedent) so the file connection closes and unlocks, then
        // remove the DB + WAL sidecars and prove it.
        cx.update(|_, cx| {
            restarted.update(cx, |view, _| {
                view.store = Store::open_in_memory().expect("swap works");
            });
        });
        for suffix in ["", "-wal", "-shm", "-journal"] {
            let sibling = std::path::PathBuf::from(format!("{}{suffix}", path.display()));
            let _ = std::fs::remove_file(&sibling);
        }
        assert!(!path.exists(), "restart temp db removed");
    }

    // -- Ticket 13: live sidecar log pipe ------------------------------------

    /// Mock sidecar emits tagged lines → drain → the logs dialog shows them
    /// under the right config with secrets redacted; an untagged line stays
    /// engine-global (never cross-config).
    #[gpui_kit::test]
    fn live_sidecar_lines_appear_under_right_config_redacted(cx: &mut TestAppContext) {
        use crate::engine::{inbound_tag, EngineController};
        use gpui_kit::component::IndexPath;

        cx.update(gpui_kit::init);

        let mut store = Store::open_in_memory().expect("in-memory store opens");
        let alpha = store.add(seed_input("Work")).expect("seed works");
        let beta = store.add(seed_input("Play")).expect("seed works");

        let stash: Rc<RefCell<Option<Entity<AppView>>>> = Rc::new(RefCell::new(None));
        let stash_for_window = stash.clone();
        let (_, cx) = cx.add_window_view(move |window, cx| {
            let view = cx.new(|cx| AppView::with_store(window, cx, store));
            *stash_for_window.borrow_mut() = Some(view.clone());
            Root::new(view, window, cx)
        });
        let view = stash.borrow().clone().expect("AppView stashed");

        let stock = cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let (controller, stock, _fork, _xray, _extra) = EngineController::fake_quartet();
                view.engine = controller;
                stock
            })
        });
        stock.emit_log(&format!(
            "warn {}: dial failed password=hunter2",
            inbound_tag(&alpha.id)
        ));
        stock.emit_log("info engine listening on 127.0.0.1:10801");

        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                // Ticket 47: ingest reuses one store list (no second scan).
                let rows = view.store.list().expect("seeded rows list");
                view.drain_engine_logs(&rows);
            });
        });

        let (alpha_lines, beta_lines) = view.read_with(cx, |view, _| {
            (
                view.logs
                    .for_config(&alpha.id)
                    .iter()
                    .map(|record| record.message.clone())
                    .collect::<Vec<_>>(),
                view.logs.for_config(&beta.id).len(),
            )
        });
        assert_eq!(alpha_lines.len(), 1, "only its lines show");
        assert!(
            !alpha_lines[0].contains("hunter2"),
            "redacted on ingest: {}",
            alpha_lines[0]
        );
        assert!(
            alpha_lines[0].contains(&inbound_tag(&alpha.id)),
            "tag preserved: {}",
            alpha_lines[0]
        );
        assert_eq!(beta_lines, 0, "no cross-config attribution");

        // The dialog renders the live lines for the selected row.
        cx.update(|window, cx| {
            view.update(cx, |view, cx| {
                view.libraries.update(cx, |state, _| {
                    state.delegate_mut().selected = Some(IndexPath::new(0));
                });
                view.reload(window, cx);
            });
        });
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.open_logs_dialog(window, cx));
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
            window.render_frame(cx);
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
            window.render_frame(cx);
        });
        // T08 (gpui-18-sweep CAP-9): logs opens as a sheet, never a dialog.
        assert!(cx.update(|window, cx| window.has_active_sheet(cx)));
        assert!(!cx.update(|window, cx| window.has_active_dialog(cx)));
        assert!(cx.update(|window, _| window.try_find("log-lines").is_some()));
    }

