    /// Scenario: honest empty start-all and stop-on-stopped toasts headless.
    #[gpui_kit::test]
    fn empty_start_and_stopped_stop_warn_honestly(cx: &mut TestAppContext) {
        use gpui_kit::component::IndexPath;
        cx.update(gpui_kit::init);
        let mut store = Store::open_in_memory().expect("in-memory store opens");
        store.add(seed_input("Work")).expect("seed works");
        let (view, cx) = mount_view(store, cx);
        // Empty-library arm first: remove the seed so start-all is honest.
        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                let rows = view.store.list().expect("list works");
                for row in &rows {
                    view.store.remove(&row.id).expect("remove works");
                }
            });
        });
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.start_all_engines(window, cx));
        });
        assert_eq!(notification_count(cx), 1, "empty start warns once");
        assert_eq!(
            view.read_with(cx, |view, _| view.engine.running_count()),
            0,
            "nothing starts"
        );

        cx.update(|_, cx| {
            view.update(cx, |view, _| {
                view.store.add(seed_input("Work")).expect("seed works");
            });
        });
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.reload(window, cx));
        });
        cx.update(|_, cx| {
            view.update(cx, |view, cx| {
                view.libraries.update(cx, |state, _| {
                    state.delegate_mut().selected = Some(IndexPath::new(0));
                });
            });
        });
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.stop_selected_engine(window, cx));
        });
        assert_eq!(notification_count(cx), 2, "stop-on-stopped warns once");
        cx.update(|window, cx| {
            view.update(cx, |view, cx| view.stop_all_engines(window, cx));
        });
        assert_eq!(notification_count(cx), 3, "idle stop-all warns once");
    }

    /// Scenario: search matches host/bind/port as well as
    /// name/protocol/group (pure matcher + delegate filter).
    #[test]
    fn library_search_matches_host_bind_port() {
        use crate::store::ProxyConfig;
        use crate::{library_row_matches, LibraryDelegate};
        fn row(name: &str, server: &str, bind: &str, port: u16) -> ProxyConfig {
            ProxyConfig {
                id: format!("id-{name}"),
                name: name.to_string(),
                protocol: "vless".to_string(),
                params: format!(
                    "{{\"type\":\"vless\",\"server\":\"{server}\",\"server_port\":443}}"
                ),
                group: "default".to_string(),
                enabled: false,
                bind_ip: bind.to_string(),
                port,
                subscription_id: None,
                identity_key: None,
                preset_id: None,
            }
        }
        let alpha = row("Alpha", "a.example.com", "127.0.0.1", 10801);
        let beta = row("Beta", "10.0.0.5", "10.0.0.5", 10802);
        assert!(library_row_matches(&beta, "10.0.0.5"), "bind/host match");
        assert!(library_row_matches(&alpha, "10801"), "port match");
        assert!(!library_row_matches(&beta, "a.example.com"));
        assert!(library_row_matches(&alpha, "a.example.com"), "host match");
        assert!(library_row_matches(&alpha, "alpha"), "name still matches");
        assert!(
            library_row_matches(&alpha, "vless"),
            "protocol still matches"
        );
        assert!(!library_row_matches(&alpha, "nope"), "no false positive");

        let mut delegate = LibraryDelegate::new();
        delegate.set_rows(vec![alpha, beta]);
        delegate.query = "10.0.0.5".to_string();
        delegate.apply_filter();
        assert_eq!(
            delegate.visible.len(),
            1,
            "filter narrows to the bind/host row"
        );
        delegate.query = "10801".to_string();
        delegate.apply_filter();
        assert_eq!(delegate.visible.len(), 1, "filter narrows by port");
        delegate.query = String::new();
        delegate.apply_filter();
        assert_eq!(delegate.visible.len(), 2, "empty query shows all");
    }

    /// Ticket 47 (RED): the delegate search index answers exactly like the
    /// per-row scan across nasty inputs — identical filter semantics
    /// (ticket 44 owns the semantics; this only caches them).
    #[test]
    fn t47_search_index_matches_scan_parity() {
        use crate::store::ProxyConfig;
        use crate::LibraryDelegate;
        fn row(
            id: &str,
            name: &str,
            protocol: &str,
            params: &str,
            group: &str,
            bind: &str,
            port: u16,
        ) -> ProxyConfig {
            ProxyConfig {
                id: id.to_string(),
                name: name.to_string(),
                protocol: protocol.to_string(),
                params: params.to_string(),
                group: group.to_string(),
                enabled: true,
                bind_ip: bind.to_string(),
                port,
                subscription_id: None,
                identity_key: None,
                preset_id: None,
            }
        }
        let rows = vec![
            row(
                "1",
                "Alpha",
                "vless",
                r#"{"server":"a.example.com","server_port":443}"#,
                "g1",
                "127.0.0.1",
                10801,
            ),
            row(
                "2",
                "Beta",
                "trojan",
                r#"{"address":"10.0.0.9","port":"8443"}"#,
                "G2",
                "::1",
                10802,
            ),
            row(
                "3",
                "Gamma Ray",
                "WIREGUARD",
                "not json{{{",
                "",
                "0.0.0.0",
                10803,
            ),
            row(
                "4",
                "Unicodae",
                "ss",
                r#"{"server":"X.EXAMPLE.COM","server_port":8388,"password":"s3cret"}"#,
                "vpn",
                "192.168.1.2",
                10804,
            ),
            row(
                "5",
                "both-hosts",
                "vless",
                r#"{"server":"nomatch.invalid","address":"matchme.invalid"}"#,
                "g1",
                "127.0.0.1",
                10805,
            ),
            row(
                "6",
                "numport",
                "tuic",
                r#"{"server":"h.example.com","server_port":12345}"#,
                "g3",
                "127.0.0.1",
                10806,
            ),
        ];
        for query in [
            "",
            "  ",
            "ALPHA",
            "vless",
            "WIREGUARD",
            "a.example.com",
            "X.EXAMPLE",
            "1080",
            "8443",
            "g1",
            "G2",
            "::1",
            "0.0.0.0",
            "gamma ray",
            "matchme",
            "nomatch",
            "s3cret",
            "nope",
            "alpha vless",
            "8388",
        ] {
            let mut delegate = LibraryDelegate::new();
            delegate.set_rows(rows.clone());
            delegate.query = query.to_string();
            delegate.apply_filter();
            let cached: Vec<String> = delegate
                .visible
                .iter()
                .map(|&i| delegate.rows[i].id.clone())
                .collect();
            let expected: Vec<String> = rows
                .iter()
                .filter(|r| crate::library_row_matches(r, query))
                .map(|r| r.id.clone())
                .collect();
            assert_eq!(cached, expected, "index parity for query {query:?}");
        }
    }

    /// Ticket 47 merge: the extended index agrees with
    /// [`library_row_matches_full`] under a non-empty context (labels,
    /// serving set, health summaries, mixed enabled flags).
    #[test]
    fn t47_search_index_matches_full_with_context() {
        use crate::store::ProxyConfig;
        use crate::{library_row_matches_full, LibraryDelegate, MatchContext};
        fn row(id: &str, name: &str, enabled: bool, sub: Option<&str>) -> ProxyConfig {
            ProxyConfig {
                id: id.to_string(),
                name: name.to_string(),
                protocol: "vless".to_string(),
                params: r#"{"server":"a.example.com","server_port":443}"#.to_string(),
                group: "g".to_string(),
                enabled,
                bind_ip: "127.0.0.1".to_string(),
                port: 10801,
                subscription_id: sub.map(str::to_string),
                identity_key: None,
                preset_id: None,
            }
        }
        let rows = vec![
            row("1", "Alpha", true, Some("s1")),
            row("2", "Beta", false, None),
        ];
        let mut ctx = MatchContext::default();
        ctx.sub_labels
            .insert("s1".to_string(), "Nightly Sub".to_string());
        ctx.running.insert("1".to_string());
        ctx.health.insert("1".to_string(), "87ms".to_string());
        ctx.health.insert("2".to_string(), "dead".to_string());
        let mut delegate = LibraryDelegate::new();
        delegate.set_rows(rows.clone());
        delegate.set_running(vec!["1".to_string()]);
        delegate.set_health(ctx.health.clone());
        delegate.set_search_context(ctx.sub_labels.clone(), ctx.preset_names.clone());
        for query in [
            "nightly",
            "sub",
            "enabled",
            "disabled",
            "running",
            "stopped",
            "live",
            "dead",
            "87ms",
            "untested",
            "alpha",
            "zzz-no-match",
        ] {
            delegate.query = query.to_string();
            delegate.apply_filter();
            let cached: Vec<String> = delegate
                .visible
                .iter()
                .map(|&i| delegate.rows[i].id.clone())
                .collect();
            let expected: Vec<String> = rows
                .iter()
                .filter(|r| library_row_matches_full(r, query, &ctx))
                .map(|r| r.id.clone())
                .collect();
            assert_eq!(cached, expected, "index/full parity for {query:?}");
        }
    }

    /// Ticket 44: group + status + protocol facets AND with the text query;
    /// visible rows satisfy every predicate at once.
    #[test]
    fn t44_facets_and_with_text_query() {
        use crate::store::ProxyConfig;
        use crate::{FacetStatus, LibraryDelegate};
        fn row(id: &str, name: &str, protocol: &str, group: &str, enabled: bool) -> ProxyConfig {
            ProxyConfig {
                id: id.to_string(),
                name: name.to_string(),
                protocol: protocol.to_string(),
                params: r#"{"server":"a.example.com","server_port":443}"#.to_string(),
                group: group.to_string(),
                enabled,
                bind_ip: "127.0.0.1".to_string(),
                port: 10801,
                subscription_id: None,
                identity_key: None,
                preset_id: None,
            }
        }
        let rows = vec![
            row("1", "Alpha", "vless", "team", true),
            row("2", "Beta", "vmess", "team", false),
            row("3", "Gamma", "vless", "lab", true),
        ];
        let mut delegate = LibraryDelegate::new();
        delegate.set_rows(rows);
        delegate.set_running(vec!["1".to_string()]);
        let mut health = std::collections::HashMap::new();
        health.insert("1".to_string(), "87ms".to_string());
        health.insert("3".to_string(), "dead".to_string());
        delegate.set_health(health);
        // Text alone matches two vless rows.
        delegate.query = "vless".to_string();
        delegate.apply_filter();
        assert_eq!(delegate.visible.len(), 2);
        // Group facet narrows to the team vless row only.
        delegate.set_facet_group(Some("team".to_string()));
        let shown: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        assert_eq!(shown, vec!["1".to_string()]);
        // Status facet ANDs further: Stopped excludes running row 1.
        delegate.set_facet_status(Some(FacetStatus::Stopped));
        assert!(delegate.visible.is_empty(), "all predicates must hold");
        delegate.set_facet_status(Some(FacetStatus::Running));
        let shown: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        assert_eq!(shown, vec!["1".to_string()]);
        // Protocol facet is exact, not substring: "VLES" matches no
        // protocol even though every vless row contains it.
        delegate.query = String::new();
        delegate.set_facet_status(None);
        delegate.set_facet_protocol(Some("VLES".to_string()));
        assert!(
            delegate.visible.is_empty(),
            "protocol is exact, not substring"
        );
        delegate.set_facet_protocol(Some("VMESS".to_string()));
        let shown: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        assert_eq!(shown, vec!["2".to_string()]);
        delegate.set_facet_group(None);
        let shown: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        assert_eq!(shown, vec!["2".to_string()]);
        // Live/Dead/Untested/Enabled/Disabled arms.
        delegate.query = String::new();
        delegate.set_facet_protocol(None);
        delegate.set_facet_status(Some(FacetStatus::Live));
        let shown: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        assert_eq!(shown, vec!["1".to_string()]);
        delegate.set_facet_status(Some(FacetStatus::Dead));
        let shown: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        assert_eq!(shown, vec!["3".to_string()]);
        delegate.set_facet_status(Some(FacetStatus::Untested));
        let shown: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        assert_eq!(shown, vec!["2".to_string()]);
        delegate.set_facet_status(Some(FacetStatus::Disabled));
        let shown: Vec<String> = delegate
            .visible
            .iter()
            .map(|&i| delegate.rows[i].id.clone())
            .collect();
        assert_eq!(shown, vec!["2".to_string()]);
        // Clearing restores the full list; query untouched by facet clears.
        delegate.query = "a".to_string();
        delegate.clear_facets();
        assert_eq!(delegate.visible.len(), 3);
        assert_eq!(delegate.query, "a");
    }

    /// Ticket 44: the bulk set survives filtering (hidden members stay
    /// checked), the label names both counts under a filter, and `set_rows`
    /// prunes vanished ids.
    #[test]
    fn t44_checked_set_honest_label_and_prune() {
        use crate::store::ProxyConfig;
        use crate::LibraryDelegate;
        fn row(id: &str, name: &str, group: &str) -> ProxyConfig {
            ProxyConfig {
                id: id.to_string(),
                name: name.to_string(),
                protocol: "vless".to_string(),
                params: r#"{"server":"a.example.com"}"#.to_string(),
                group: group.to_string(),
                enabled: true,
                bind_ip: "127.0.0.1".to_string(),
                port: 10801,
                subscription_id: None,
                identity_key: None,
                preset_id: None,
            }
        }
        let mut delegate = LibraryDelegate::new();
        delegate.set_rows(vec![
            row("1", "Alpha", "g"),
            row("2", "Beta", "g"),
            row("3", "Gamma", "g"),
        ]);
        assert_eq!(delegate.bulk_label(), "");
        delegate.toggle_checked("1");
        delegate.toggle_checked("3");
        delegate.toggle_checked("ghost");
        assert_eq!(delegate.checked.len(), 2, "unknown ids never check");
        assert_eq!(delegate.bulk_label(), "2 checked (of 3 visible)");
        // Filter hides a member: set intact, label honest, rows in order.
        delegate.query = "alpha".to_string();
        delegate.apply_filter();
        assert_eq!(delegate.checked.len(), 2);
        assert_eq!(delegate.bulk_label(), "2 checked (of 1 visible)");
        let checked: Vec<String> = delegate
            .checked_rows()
            .iter()
            .map(|r| r.id.clone())
            .collect();
        assert_eq!(checked, vec!["1".to_string(), "3".to_string()]);
        // Facets also drive the `(M visible)` arm.
        delegate.query = String::new();
        delegate.set_facet_group(Some("nope".to_string()));
        assert_eq!(delegate.bulk_label(), "2 checked (of 0 visible)");
        delegate.clear_facets();
        // Reload without row 3 prunes it; toggle twice round-trips.
        delegate.set_rows(vec![row("1", "Alpha", "g"), row("2", "Beta", "g")]);
        assert_eq!(delegate.checked.len(), 1);
        assert_eq!(delegate.bulk_label(), "1 checked (of 2 visible)");
        delegate.toggle_checked("1");
        assert_eq!(delegate.bulk_label(), "");
        delegate.clear_checked();
        assert_eq!(delegate.bulk_label(), "");
    }

    /// Ticket 09 (throne-adoption): Show-Security splices the posture into
    /// the meta line only when on; `Type|Security` reorders the visible
    /// indices only (store order untouched).
    #[test]
    fn t09_show_security_and_type_security_sort() {
        use crate::apply_show_security;
        use crate::store::ProxyConfig;
        use crate::LibraryDelegate;
        fn row(id: &str, name: &str, protocol: &str, params: &str) -> ProxyConfig {
            ProxyConfig {
                id: id.to_string(),
                name: name.to_string(),
                protocol: protocol.to_string(),
                params: params.to_string(),
                group: "g".to_string(),
                enabled: true,
                bind_ip: "127.0.0.1".to_string(),
                port: 10801,
                subscription_id: None,
                identity_key: None,
                preset_id: None,
            }
        }
        let tls_row = row("1", "A", "vless", r#"{"security":"tls"}"#);
        let mut lines = vec![
            "A".to_string(),
            "vless · h:1".to_string(),
            "badge".to_string(),
        ];
        apply_show_security(&mut lines, &tls_row);
        assert_eq!(lines[1], "vless · h:1 · tls", "posture spliced");
        assert_eq!(lines.len(), 3, "no new lines");
        let mut delegate = LibraryDelegate::new();
        delegate.set_rows(vec![
            row("1", "T", "trojan", "{}"),
            row("2", "Vtls", "vless", r#"{"security":"tls"}"#),
            row("3", "Vreal", "vless", r#"{"security":"reality"}"#),
        ]);
        let order = |delegate: &LibraryDelegate| {
            delegate
                .visible
                .iter()
                .map(|&index| delegate.rows[index].name.clone())
                .collect::<Vec<_>>()
        };
        assert_eq!(order(&delegate), vec!["T", "Vtls", "Vreal"]);
        delegate.set_type_security_sort(true);
        assert_eq!(order(&delegate), vec!["T", "Vreal", "Vtls"]);
        assert_eq!(
            delegate
                .rows
                .iter()
                .map(|row| row.name.clone())
                .collect::<Vec<_>>(),
            vec!["T", "Vtls", "Vreal"],
            "store order untouched"
        );
        assert!(!delegate.show_security);
        delegate.set_show_security(true);
        assert!(delegate.show_security);
    }

    /// Ticket 09 (throne-adoption): group/speed/out-ip/resolve texts name
    /// their scope (never a blind toast).
    #[test]
    fn t09_group_toast_texts_name_scope() {
        use crate::health::{SpeedtestMode, SpeedtestOutcome};
        use crate::{
            group_test_summary_toast, out_ip_summary_toast, resolve_domain_confirm_text,
            resolve_domain_result_message, speed_result_toast, speed_test_summary_toast,
        };
        assert_eq!(
            group_test_summary_toast("g", 3, 2, 1, false),
            "Tested 3 endpoint(s) in group \"g\": 2 live · 1 dead"
        );
        assert!(
            group_test_summary_toast("g", 3, 1, 0, true).contains("(stopped early)"),
            "stop marked"
        );
        assert_eq!(
            speed_test_summary_toast("in group \"g\"", SpeedtestMode::Download, 2, 1),
            "Speedtest (download): in group \"g\": 2 measured · 1 failed"
        );
        let measured = SpeedtestOutcome {
            config_id: "1".to_string(),
            mode: SpeedtestMode::Download,
            latency_ms: Some(40),
            mbps: Some(24.5),
            error: None,
        };
        assert_eq!(
            speed_result_toast("A", &measured),
            "Speedtest \"A\": download 24.5 Mbps"
        );
        let failed = SpeedtestOutcome {
            config_id: "1".to_string(),
            mode: SpeedtestMode::Upload,
            latency_ms: None,
            mbps: None,
            error: Some("dial refused".to_string()),
        };
        assert_eq!(
            speed_result_toast("A", &failed),
            "Speedtest \"A\": failed — dial refused"
        );
        assert_eq!(
            out_ip_summary_toast("of \"A\"", &["1.2.3.4".to_string()], &[]),
            "Out-IP of \"A\": 1.2.3.4"
        );
        assert_eq!(
            out_ip_summary_toast(
                "in group \"g\"",
                &["1.2.3.4".to_string(), "1.2.3.4".to_string()],
                &["\"B\": egress down".to_string()]
            ),
            "Out-IP in group \"g\": 1.2.3.4 · 1 failed: \"B\": egress down"
        );
        let names: Vec<String> = (0..25).map(|i| format!("R{i}")).collect();
        let confirm = resolve_domain_confirm_text("g", &names);
        assert!(confirm.contains("\"g\""), "names scope: {confirm}");
        assert!(confirm.contains("25"), "names count: {confirm}");
        assert!(confirm.contains("+5 more"), "overflow named: {confirm}");
        assert_eq!(
            resolve_domain_result_message(&[], &[]),
            "Resolve domain: nothing to rewrite"
        );
        let rewritten = vec![(
            "A".to_string(),
            "a.example.com".to_string(),
            "93.184.216.34".to_string(),
        )];
        let message = resolve_domain_result_message(&rewritten, &["\"B\": nope".to_string()]);
        assert!(
            message.contains("\"A\": a.example.com → 93.184.216.34"),
            "names rewrite: {message}"
        );
        assert!(message.contains("1 failed"), "names failures: {message}");
    }

    /// Ticket 01: selection grammar at the delegate seam — checked rows
    /// carry 1-based count-chip positions in library order while the wash
    /// (selection) names a different row; the bulk label names both
    /// counts; selection and checks never retarget each other.
    #[test]
    fn t01_checked_positions_and_selection_stay_distinct() {
        use crate::store::ProxyConfig;
        use crate::LibraryDelegate;
        use gpui_kit::component::IndexPath;
        fn row(id: &str, name: &str) -> ProxyConfig {
            ProxyConfig {
                id: id.to_string(),
                name: name.to_string(),
                protocol: "vless".to_string(),
                params: r#"{"server":"a.example.com"}"#.to_string(),
                group: "g".to_string(),
                enabled: true,
                bind_ip: "127.0.0.1".to_string(),
                port: 10801,
                subscription_id: None,
                identity_key: None,
                preset_id: None,
            }
        }
        let mut delegate = LibraryDelegate::new();
        delegate.set_rows(vec![row("1", "Alpha"), row("2", "Beta"), row("3", "Gamma")]);
        delegate.toggle_checked("1");
        delegate.toggle_checked("3");
        delegate.selected = Some(IndexPath::new(2));
        assert_eq!(delegate.checked_position("1"), Some(1));
        assert_eq!(delegate.checked_position("3"), Some(2));
        assert_eq!(
            delegate.checked_position("2"),
            None,
            "the selected-only row carries no chip"
        );
        assert_eq!(delegate.bulk_label(), "2 checked (of 3 visible)");
        assert_eq!(
            delegate.selected_row().map(|row| row.name),
            Some("Gamma".to_string()),
            "the wash names the selected row"
        );
        assert_eq!(
            delegate
                .checked_rows()
                .iter()
                .map(|row| row.id.clone())
                .collect::<Vec<_>>(),
            vec!["1".to_string(), "3".to_string()],
            "bulk acts on the checked set, never the selection"
        );
        // Unchecking re-numbers the chips; clearing selection keeps checks.
        delegate.toggle_checked("1");
        assert_eq!(delegate.checked_position("3"), Some(1));
        assert_eq!(delegate.bulk_label(), "1 checked (of 3 visible)");
        delegate.clear_selection();
        assert_eq!(
            delegate.checked.len(),
            1,
            "checks survive a selection clear"
        );
    }

